package co.edu.corhuila.property.payment.domain.model;

import java.util.UUID;

/** Identifier of the Pago aggregate. Generated by the domain on creation. */
public record PagoId(UUID value) {

    public PagoId {
        if (value == null) {
            throw new DomainException("El id del pago es requerido");
        }
    }

    public static PagoId nueva() {
        return new PagoId(UUID.randomUUID());
    }
}
